<script setup>
import{ref,onMounted}from'vue';
import{requestApi}from'../../shared/infrastructure/http/apiClient.js';
import{apiUrl}from'../../shared/infrastructure/http/apiUrl.js';
import{submitOperation,pendingOperations,retryOperation}from'../../shared/infrastructure/http/pendingOperation.js';
const props=defineProps({identity:Object,online:Boolean}),list=ref([]),detail=ref(null),eligibility=ref(null),error=ref(''),notice=ref(''),busy=ref(false),pending=ref([]);
const productId=ref(''),filterProduct=ref(''),filterStatus=ref(''),issuerName=ref(''),reviewReason=ref(''),decision=ref('Issue'),revokeReason=ref(''),revokeEvidence=ref('');
const labels={PendingReview:'Pendiente de revisión',Issued:'Emitido',Revoked:'Revocado',Rejected:'Rechazado',ReviewRequired:'Requiere nueva revisión',UnableToVerify:'Vigencia sin confirmar'};
const can=p=>props.identity.permissions.includes(p),scope=()=>({tenantId:props.identity.tenantId,userId:props.identity.userId,resourceId:'certificates'});
async function load(){try{const query=new URLSearchParams();if(filterProduct.value)query.set('productId',filterProduct.value.trim());if(filterStatus.value)query.set('status',filterStatus.value);list.value=(await requestApi('/api/v1/certificates?'+query)).certificates;pending.value=pendingOperations(scope());}catch(e){error.value=e.message;}}
onMounted(load);
async function view(id){error.value='';eligibility.value=null;try{detail.value=await requestApi(`/api/v1/certificates/${id}`);if(can('certificates.review'))eligibility.value=await requestApi(`/api/v1/certificates/${id}/eligibility`);}catch(e){error.value=e.message;}}
async function act(action,path,payload){busy.value=true;error.value='';notice.value='';try{const result=await submitOperation(path,payload,scope(),action);notice.value=`Certificado ${labels[result.status]??result.status}.`;await load();await view(result.certificateId);}catch(e){error.value=e.message;pending.value=pendingOperations(scope());}finally{busy.value=false;}}
async function download(){busy.value=true;error.value='';try{const response=await fetch(apiUrl(`/api/v1/certificates/${detail.value.certificateId}/pdf`),{credentials:'include'});if(response.status===202){notice.value='PDF pendiente. Usa Descargar PDF nuevamente cuando finalice la generación.';return;}if(!response.ok){const body=await response.json();throw Error(body.error?.message??'PDF sin confirmar; vuelve a intentar.');}const url=URL.createObjectURL(await response.blob()),anchor=document.createElement('a');anchor.href=url;anchor.download=`eventore-${detail.value.certificateId}.pdf`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='PDF descargado. Su QR consulta el estado vigente.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function retry(attempt){busy.value=true;try{const result=await retryOperation(attempt);await load();await view(result.certificateId);}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="panel" aria-label="Certificación"><h2>Certificación</h2><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert" role="status">{{notice}}</p>
 <p v-for="attempt in pending" :key="attempt.key" class="alert">Solicitud sin confirmar. <button :disabled="busy||!online" @click="retry(attempt)">Reintentar certificado</button></p>
 <form v-if="can('certificates.request')" @submit.prevent="act('request','/api/v1/certificates',{productId:productId.trim()})"><h3>Solicitar revisión</h3><label>ID de joya para certificar<input v-model="productId" required /></label><button :disabled="busy||!online">Solicitar certificado</button><p class="muted">La solicitud queda pendiente. La emisión requiere revisar la genealogía y toda la evidencia relevante.</p></form>
 <form @submit.prevent="load"><div class="formrow"><label>Filtrar certificados por joya<input v-model="filterProduct" /></label><label>Estado registrado<select v-model="filterStatus"><option value="">Todos</option><option v-for="status in ['PendingReview','Issued','Rejected','Revoked']" :key="status" :value="status">{{labels[status]}}</option></select></label></div><button class="secondary" :disabled="!online">Filtrar certificados</button></form>
 <ul class="history-list"><li v-for="cert in list" :key="cert.id"><strong>{{labels[cert.status]}}</strong><p class="identifier">{{cert.id}}</p><p>Joya {{cert.productId}} · composición {{cert.productVersion}}</p><p>{{new Date(cert.issuedAt??cert.createdAt).toLocaleString('es-PE')}}</p><button class="secondary" @click="view(cert.id)">Consultar certificado</button></li></ul><p v-if="!list.length">No hay certificados que coincidan.</p>
 <section v-if="detail" class="lot-operations" aria-label="Detalle de certificado"><h3>{{detail.current.product.name}}</h3><p class="identifier">{{detail.certificateId}}</p><p role="status">Estado actual: {{labels[detail.current.status]??detail.current.status}}</p><p>Versión de composición revisada: {{detail.productVersion}}</p><p class="identifier">Evidencia: {{detail.current.evidenceVersion??'Sin revisión favorable'}}</p><a :href="'/verify/'+detail.certificateId" target="_blank" rel="noopener">Abrir consulta pública</a>
  <div v-if="eligibility"><h4>Evaluación de genealogía</h4><p>{{eligibility.eligible?'Condiciones de evidencia satisfechas':'Evidencia insuficiente para emitir'}}</p><ul><li v-for="(issue,index) in eligibility.issues" :key="index">{{issue.code}} <span class="identifier">{{issue.lotId??issue.materialId}}</span></li></ul></div>
  <form v-if="can('certificates.review')&&['PendingReview','Rejected'].includes(detail.status)" @submit.prevent="act('review','/api/v1/certificates/'+detail.certificateId+'/review',{expectedVersion:detail.version,decision,issuerName,reason:reviewReason})"><label>Decisión del certificado<select v-model="decision"><option value="Issue">Emitir tras revisión favorable</option><option value="Reject">Rechazar solicitud</option></select></label><label>Nombre del emisor<input v-model="issuerName" required maxlength="200" /></label><label>Motivo de revisión del certificado<input v-model="reviewReason" required /></label><button :disabled="busy||!online||(decision==='Issue'&&!eligibility?.eligible)">Registrar decisión del certificado</button></form>
  <button v-if="detail.current.status==='Issued'" :disabled="busy||!online" @click="download">Descargar PDF</button>
  <form v-if="can('certificates.revoke')&&detail.status==='Issued'" @submit.prevent="act('revoke','/api/v1/certificates/'+detail.certificateId+'/revoke',{expectedVersion:detail.version,reason:revokeReason,evidenceRef:revokeEvidence})"><h4>Revocar emisión</h4><label>Motivo de revocación<input v-model="revokeReason" required /></label><label>Evidencia de revocación<input v-model="revokeEvidence" required /></label><button :disabled="busy||!online">Revocar certificado</button></form>
  <h4>Historial autorizado</h4><ol><li v-for="(event,index) in detail.history" :key="index">{{event.action}} · {{new Date(event.occurredAt).toLocaleString('es-PE')}}<p>{{event.command.reason??'Solicitud inicial'}}</p><p v-if="event.command.evidenceRef">Evidencia: {{event.command.evidenceRef}}</p></li></ol>
 </section>
</section></template>
